// Small real files of the kinds a scene couldn't make before (16 Nov 2026, the 800-job read: 32 of its 47 test-world
// faults were sound, video, program, PowerPoint and Photoshop files the scene asked for and the test home skipped, so
// Bob was asked about a file that wasn't there). Each is a real file of its kind that the usual players and readers
// open: a short tone, a second of grey video, a do-nothing Windows program, a slide deck with the scene's words, a
// one-colour Photoshop picture. The sound and video samples were made once with ffmpeg (sine tone, grey frames, no
// details inside); everything else is built here byte by byte. No libraries, nothing downloaded, nothing that runs
// anything: the program's only instruction is "return".
import zlib from 'node:zlib';
import { zipStore } from './scene-files.mjs';

const MEDIA = {
  mp3: '',
  flac: '',
  ogg: '',
  m4a: '',
  mp4: '',
  mov: '',
  mkv: '',
  webm: '',
  avi: '',
  gif: '',
  webp: 'UklGRiQAAABXRUJQVlA4IBgAAABQAQCdASoQABAAAgA0JaQABHQAAORAAAA=',
  tiff: '',
  bmp: '',
  ico: ''
};
export const MEDIA_EXT = Object.keys(MEDIA);
const pick = (meta, ...keys) => { for (const k of keys) for (const [mk, v] of Object.entries(meta || {})) if (mk.toLowerCase() === k.toLowerCase() && v != null && String(v).trim()) return String(v).trim(); return ''; };
const xml = (s) => String(s ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const lines = (t) => String(t ?? '').replace(/\r\n?/g, '\n').split('\n');

// ---- sound: an ID3 tag (title, artist, album, year, comment) on the MP3; WAV built here with its INFO details ----
function id3(meta) {
  const ss = (n) => Buffer.from([(n >> 21) & 0x7f, (n >> 14) & 0x7f, (n >> 7) & 0x7f, n & 0x7f]);
  const frame = (id, body) => Buffer.concat([Buffer.from(id, 'latin1'), ss(body.length), Buffer.from([0, 0]), body]);
  const text = (id, v) => frame(id, Buffer.concat([Buffer.from([3]), Buffer.from(v, 'utf8')]));
  const frames = [['TIT2', pick(meta, 'Title')], ['TPE1', pick(meta, 'Artist', 'Author')], ['TALB', pick(meta, 'Album')], ['TDRC', pick(meta, 'Year', 'Date', 'DateTaken')], ['TCON', pick(meta, 'Genre')], ['TRCK', pick(meta, 'Track')]]
    .filter(([, v]) => v).map(([id, v]) => text(id, v.slice(0, 200)));
  const c = pick(meta, 'Comment', 'Comments', 'Description');
  if (c) frames.push(frame('COMM', Buffer.concat([Buffer.from([3]), Buffer.from('eng\0', 'latin1'), Buffer.from(c.slice(0, 500), 'utf8')])));
  if (!frames.length) return Buffer.alloc(0);
  const body = Buffer.concat(frames);
  return Buffer.concat([Buffer.from('ID3', 'latin1'), Buffer.from([4, 0, 0]), ss(body.length), body]);
}
export function wav(meta = {}) {
  const rate = 8000, n = rate / 2, data = Buffer.alloc(n);
  for (let i = 0; i < n; i++) data[i] = 128 + Math.round(40 * Math.sin((2 * Math.PI * 440 * i) / rate)); // half a second of a quiet tone
  const info = [['INAM', pick(meta, 'Title')], ['IART', pick(meta, 'Artist', 'Author')], ['ICMT', pick(meta, 'Comment', 'Comments', 'Description')], ['ICRD', pick(meta, 'Date', 'Year', 'DateTaken')], ['ISFT', pick(meta, 'Software')]]
    .filter(([, v]) => v).map(([id, v]) => { let b = Buffer.from(v.slice(0, 300) + '\0', 'utf8'); if (b.length & 1) b = Buffer.concat([b, Buffer.alloc(1)]); const h = Buffer.alloc(8); h.write(id, 0, 'latin1'); h.writeUInt32LE(b.length, 4); return Buffer.concat([h, b]); });
  const list = info.length ? (() => { const body = Buffer.concat([Buffer.from('INFO', 'latin1'), ...info]); const h = Buffer.alloc(8); h.write('LIST', 0, 'latin1'); h.writeUInt32LE(body.length, 4); return Buffer.concat([h, body]); })() : Buffer.alloc(0);
  const fmt = Buffer.alloc(24); fmt.write('fmt ', 0, 'latin1'); fmt.writeUInt32LE(16, 4); fmt.writeUInt16LE(1, 8); fmt.writeUInt16LE(1, 10); fmt.writeUInt32LE(rate, 12); fmt.writeUInt32LE(rate, 16); fmt.writeUInt16LE(1, 20); fmt.writeUInt16LE(8, 22);
  const dh = Buffer.alloc(8); dh.write('data', 0, 'latin1'); dh.writeUInt32LE(n, 4);
  const body = Buffer.concat([Buffer.from('WAVE', 'latin1'), fmt, list, dh, data]);
  const rh = Buffer.alloc(8); rh.write('RIFF', 0, 'latin1'); rh.writeUInt32LE(body.length, 4);
  return Buffer.concat([rh, body]);
}
export function media(ext, meta = {}) {
  const e = String(ext || '').toLowerCase().replace(/^\./, '');
  if (e === 'wav') return wav(meta);
  if (e === 'jfif') return null;
  const b64 = MEDIA[e === 'tif' ? 'tiff' : e === 'm4v' ? 'mp4' : e];
  if (!b64) return null;
  const b = Buffer.from(b64, 'base64');
  return e === 'mp3' ? Buffer.concat([id3(meta), b]) : b;
}

// ---- a Windows program (.exe) or library (.dll) that does nothing: one section whose code is "return" ----
// A real PE file (MZ and PE headers, one .text section); its build date is the scene's "Date" if it gives one.
export function pe({ dll = false, meta = {} } = {}) {
  const b = Buffer.alloc(0x400);
  b.write('MZ', 0, 'latin1'); b.writeUInt32LE(0x40, 0x3c);
  b.write('PE\0\0', 0x40, 'latin1');
  const when = Date.parse(pick(meta, 'Date', 'Built', 'Compiled', 'Timestamp')) || Date.UTC(2024, 0, 15);
  const c = 0x44; b.writeUInt16LE(0x14c, c); b.writeUInt16LE(1, c + 2); b.writeUInt32LE(Math.floor(when / 1000) >>> 0, c + 4); b.writeUInt16LE(0xe0, c + 16); b.writeUInt16LE(dll ? 0x2102 : 0x0102, c + 18);
  const o = 0x58;
  b.writeUInt16LE(0x10b, o); b[o + 2] = 14; b.writeUInt32LE(0x200, o + 4); b.writeUInt32LE(0x1000, o + 16); b.writeUInt32LE(0x1000, o + 20); b.writeUInt32LE(0x2000, o + 24);
  b.writeUInt32LE(0x400000, o + 28); b.writeUInt32LE(0x1000, o + 32); b.writeUInt32LE(0x200, o + 36); b.writeUInt16LE(6, o + 40); b.writeUInt16LE(6, o + 48);
  b.writeUInt32LE(0x2000, o + 56); b.writeUInt32LE(0x200, o + 60); b.writeUInt16LE(2, o + 68); b.writeUInt16LE(0x8500, o + 70);
  b.writeUInt32LE(0x100000, o + 72); b.writeUInt32LE(0x1000, o + 76); b.writeUInt32LE(0x100000, o + 80); b.writeUInt32LE(0x1000, o + 84); b.writeUInt32LE(16, o + 92);
  const s = o + 0xe0; b.write('.text', s, 'latin1'); b.writeUInt32LE(8, s + 8); b.writeUInt32LE(0x1000, s + 12); b.writeUInt32LE(0x200, s + 16); b.writeUInt32LE(0x200, s + 20); b.writeUInt32LE(0x60000020, s + 36);
  Buffer.from(dll ? [0xb8, 1, 0, 0, 0, 0xc2, 0x0c, 0] : [0x31, 0xc0, 0xc3]).copy(b, 0x200); // dll: return TRUE; exe: return 0
  return b;
}

// ---- a Photoshop picture (.psd): 16 x 16, one colour, no layers ----
export function psd() {
  const w = 16, h = 16, head = Buffer.alloc(26);
  head.write('8BPS', 0, 'latin1'); head.writeUInt16BE(1, 4); head.writeUInt16BE(3, 12); head.writeUInt32BE(h, 14); head.writeUInt32BE(w, 18); head.writeUInt16BE(8, 22); head.writeUInt16BE(3, 24);
  const img = Buffer.concat([Buffer.alloc(2), Buffer.alloc(w * h, 90), Buffer.alloc(w * h, 120), Buffer.alloc(w * h, 160)]);
  return Buffer.concat([head, Buffer.alloc(4), Buffer.alloc(4), Buffer.alloc(4), img]);
}

// ---- archives: .tar, .tar.gz/.tgz with the scene's "inside" files; .gz of one file's text ----
export function tar(entries) {
  const out = [];
  for (const { name, data } of entries) {
    const d = Buffer.isBuffer(data) ? data : Buffer.from(String(data ?? ''), 'utf8'), h = Buffer.alloc(512);
    h.write(String(name).slice(0, 99), 0, 'utf8'); h.write('0000644\0', 100, 'latin1'); h.write('0000000\0', 108, 'latin1'); h.write('0000000\0', 116, 'latin1');
    h.write(d.length.toString(8).padStart(11, '0') + '\0', 124, 'latin1'); h.write(Math.floor(Date.UTC(2024, 0, 15) / 1000).toString(8).padStart(11, '0') + '\0', 136, 'latin1');
    h.write('        ', 148, 'latin1'); h[156] = 0x30; h.write('ustar\0', 257, 'latin1'); h.write('00', 263, 'latin1');
    let sum = 0; for (const x of h) sum += x; h.write(sum.toString(8).padStart(6, '0') + '\0 ', 148, 'latin1');
    out.push(h, d, Buffer.alloc((512 - (d.length % 512)) % 512));
  }
  out.push(Buffer.alloc(1024));
  return Buffer.concat(out);
}
export const gzip = (buf) => zlib.gzipSync(buf, { level: 9 });

// ---- Rich Text (.rtf) with the scene's words ----
export function rtf(text, meta = {}) {
  const esc = (s) => String(s).replace(/[\\{}]/g, '\\$&').replace(/[^\x00-\x7f]/g, (ch) => { const n = ch.charCodeAt(0); return `\\u${n > 32767 ? n - 65536 : n}?`; });
  const info = [['title', pick(meta, 'Title')], ['author', pick(meta, 'Author', 'Creator')], ['company', pick(meta, 'Company')], ['comment', pick(meta, 'Comments', 'Comment')]].filter(([, v]) => v).map(([k, v]) => `{\\${k} ${esc(v)}}`).join('');
  return Buffer.from(`{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Calibri;}}${info ? `{\\info${info}}` : ''}\\f0\\fs22 ${lines(text).map((l) => esc(l)).join('\\par\n')}\\par}`, 'latin1');
}

// ---- PowerPoint (.pptx): a slide per "Slide" block (or per blank-line block), title and points from the scene's text ----
const NS = 'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"';
const HEAD = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';
const REL = (rels) => `${HEAD}<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${rels.map(([id, type, target]) => `<Relationship Id="${id}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/${type}" Target="${target}"/>`).join('')}</Relationships>`;
const TREE = (shapes) => `<p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/>${shapes}</p:spTree></p:cSld>`;
const box = (id, name, y, h, paras, size) => `<p:sp><p:nvSpPr><p:cNvPr id="${id}" name="${name}"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="457200" y="${y}"/><a:ext cx="8229600" cy="${h}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr><p:txBody><a:bodyPr/><a:lstStyle/>${paras.map((t) => `<a:p><a:r><a:rPr lang="en-US" sz="${size}"/><a:t>${xml(t)}</a:t></a:r></a:p>`).join('') || '<a:p/>'}</p:txBody></p:sp>`;
const THEME = `${HEAD}<a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="Plain"><a:themeElements><a:clrScheme name="Plain"><a:dk1><a:srgbClr val="000000"/></a:dk1><a:lt1><a:srgbClr val="FFFFFF"/></a:lt1><a:dk2><a:srgbClr val="44546A"/></a:dk2><a:lt2><a:srgbClr val="E7E6E6"/></a:lt2>${['4472C4', 'ED7D31', 'A5A5A5', 'FFC000', '5B9BD5', '70AD47'].map((c, i) => `<a:accent${i + 1}><a:srgbClr val="${c}"/></a:accent${i + 1}>`).join('')}<a:hlink><a:srgbClr val="0563C1"/></a:hlink><a:folHlink><a:srgbClr val="954F72"/></a:folHlink></a:clrScheme><a:fontScheme name="Plain"><a:majorFont><a:latin typeface="Calibri"/><a:ea typeface=""/><a:cs typeface=""/></a:majorFont><a:minorFont><a:latin typeface="Calibri"/><a:ea typeface=""/><a:cs typeface=""/></a:minorFont></a:fontScheme><a:fmtScheme name="Plain"><a:fillStyleLst><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:fillStyleLst><a:lnStyleLst><a:ln w="6350"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln><a:ln w="12700"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln><a:ln w="19050"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln></a:lnStyleLst><a:effectStyleLst><a:effectStyle><a:effectLst/></a:effectStyle><a:effectStyle><a:effectLst/></a:effectStyle><a:effectStyle><a:effectLst/></a:effectStyle></a:effectStyleLst><a:bgFillStyleLst><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:bgFillStyleLst></a:fmtScheme></a:themeElements></a:theme>`;
export function slidesOf(text) {
  const t = String(text ?? '').replace(/\r\n?/g, '\n').trim();
  const parts = /^\s*(?:#+\s*)?slide\s*\d+\b/im.test(t) ? t.split(/\n(?=\s*(?:#+\s*)?slide\s*\d+\b)/i) : t.split(/\n\s*\n/);
  return parts.map((p) => p.split('\n').map((l) => l.trim()).filter(Boolean)).filter((p) => p.length).slice(0, 40)
    .map((p) => ({ title: p[0].replace(/^#+\s*/, '').replace(/^slide\s*\d+\s*[:.\-–]\s*/i, '') || p[0], points: p.slice(1).map((l) => l.replace(/^[-*•]\s*/, '')) }));
}
export function pptx(text, meta = {}, coreApp = null) {
  const slides = slidesOf(text); if (!slides.length) slides.push({ title: pick(meta, 'Title') || 'Slide 1', points: [] });
  const n = slides.length;
  const files = [
    { name: '[Content_Types].xml', data: `${HEAD}<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/><Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/><Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/><Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>${slides.map((_, i) => `<Override PartName="/ppt/slides/slide${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>`).join('')}<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/><Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/></Types>` },
    { name: '_rels/.rels', data: `${HEAD}<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="ppt/presentation.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/></Relationships>` },
    { name: 'ppt/presentation.xml', data: `${HEAD}<p:presentation ${NS}><p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId1"/></p:sldMasterIdLst><p:sldIdLst>${slides.map((_, i) => `<p:sldId id="${256 + i}" r:id="rId${i + 3}"/>`).join('')}</p:sldIdLst><p:sldSz cx="9144000" cy="6858000"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>` },
    { name: 'ppt/_rels/presentation.xml.rels', data: REL([['rId1', 'slideMaster', 'slideMasters/slideMaster1.xml'], ['rId2', 'theme', 'theme/theme1.xml'], ...slides.map((_, i) => [`rId${i + 3}`, 'slide', `slides/slide${i + 1}.xml`])]) },
    { name: 'ppt/slideMasters/slideMaster1.xml', data: `${HEAD}<p:sldMaster ${NS}>${TREE('')}<p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/><p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="rId1"/></p:sldLayoutIdLst></p:sldMaster>` },
    { name: 'ppt/slideMasters/_rels/slideMaster1.xml.rels', data: REL([['rId1', 'slideLayout', '../slideLayouts/slideLayout1.xml'], ['rId2', 'theme', '../theme/theme1.xml']]) },
    { name: 'ppt/slideLayouts/slideLayout1.xml', data: `${HEAD}<p:sldLayout ${NS} type="blank">${TREE('')}<p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>` },
    { name: 'ppt/slideLayouts/_rels/slideLayout1.xml.rels', data: REL([['rId1', 'slideMaster', '../slideMasters/slideMaster1.xml']]) },
    { name: 'ppt/theme/theme1.xml', data: THEME },
    ...slides.flatMap((s, i) => [
      { name: `ppt/slides/slide${i + 1}.xml`, data: `${HEAD}<p:sld ${NS}>${TREE(box(2, 'Title', 457200, 1143000, [s.title], 3600) + box(3, 'Text', 1828800, 4572000, s.points, 2000))}<p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>` },
      { name: `ppt/slides/_rels/slide${i + 1}.xml.rels`, data: REL([['rId1', 'slideLayout', '../slideLayouts/slideLayout1.xml']]) }
    ]),
    { name: 'docProps/core.xml', data: coreApp?.core || `${HEAD}<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/"/>` },
    { name: 'docProps/app.xml', data: coreApp?.app || `${HEAD}<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties"><Slides>${n}</Slides></Properties>` }
  ];
  return zipStore(files);
}
